func ParseList(s string) []string {
	var out []string
	for len(s) > 0 {
		part := s
		if idx := strings.IndexByte(s, ','); idx >= 0 {
			part, s = s[:idx], s[idx+1:]
		} else {
			s = ""
		}
		if p := strings.TrimSpace(part); p != "" {
			out = append(out, p)
		}
	}
	return out
}

